        if (each.stream().anyMatch(t -> t.length() > 140)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A tag is at most 140 characters.");
        }
        return each.isEmpty() ? null : String.join(",", each);
    }

